// Some portions generated by Co-Pilot
"use client";

import React, { useEffect, useId, useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { useSearchParams } from "next/navigation";
import ReleaseSelector from "@/components/Marketplace/ReleaseSelector";
import VendorSelector from "@/components/Marketplace/VendorSelector";
import AllReleaseCard from "@/components/Marketplace/AllReleasesCard";

import { setURLParam } from "@/utils/setURLParam";
import { detectOS, UserOS } from "@/utils/detectOS";
import {
  packageTypes,
  defaultArchitecture,
  defaultPackageType,
} from "@/utils/defaults";
import getVendorIdentifier from "@/utils/vendors";
import { getAllPkgsForVersion, MarketplaceRelease } from "@/hooks";
import type {
  OperatingSystem,
  Architecture,
  ImageType,
} from "@/hooks/fetchMarketplace";
import type { MarketplaceVendor } from "@/services/adoptiumApi";
import { useArches, useOses } from "@/hooks/fetchConstants";
import vendors from "@/data/marketplace.json";
import { FiChevronDown, FiRotateCcw } from "react-icons/fi";

interface DownloadTableProps {
  ltsVersions: { name: string; value: string }[];
  latestLTS?: number;
}

const marketplaceVendors: MarketplaceVendor[] = [
  "adoptium",
  "alibaba",
  "ibm",
  "microsoft",
  "azul",
];
function toMarketplaceVendors(identifiers: string[]): MarketplaceVendor[] {
  return identifiers.map((identifier) => {
    const vendor = marketplaceVendors.find((vendor) => vendor === identifier);
    if (!vendor)
      throw new Error(`Unsupported Marketplace vendor: ${identifier}`);
    return vendor;
  });
}
const defaultVendors = toMarketplaceVendors(vendors.map(getVendorIdentifier));

interface MarketplaceRequest {
  key: string;
  releases: MarketplaceRelease[] | null;
  failed: boolean;
}

const DownloadTable: React.FC<DownloadTableProps> = ({
  ltsVersions,
  latestLTS,
}) => {
  const t = useTranslations("Marketplace");
  const tFilters = useTranslations("Temurin.Releases.ReleaseFilters");
  const rawOses = useOses(true);
  const rawArches = useArches(true);
  const oses = useMemo(
    () =>
      rawOses.map((option) => ({
        name:
          option.value === "mac"
            ? "macOS"
            : option.value === "alpine-linux"
              ? "Alpine Linux"
              : option.name,
        value: option.value === "alpine-linux" ? "alpine_linux" : option.value,
      })),
    [rawOses],
  );
  const arches = useMemo(
    () =>
      rawArches
        .map((option) => ({
          ...option,
          value: option.value === "x32" ? "x86" : option.value,
        }))
        .filter(
          (option, index, options) =>
            options.findIndex((other) => other.value === option.value) ===
            index,
        ),
    [rawArches],
  );
  const [ready, setReady] = useState(false);
  const searchParams = useSearchParams();
  const filterPanelId = useId();
  const [filtersOpen, setFiltersOpen] = useState(false);

  const [os, updateOS] = useState<OperatingSystem>("any");
  const [arch, updateArch] = useState<Architecture>(defaultArchitecture);
  const [version, updateVersion] = useState(String(latestLTS ?? 25));
  const [packageType, updatePackageType] =
    useState<ImageType>(defaultPackageType);
  const [selectedVendorIdentifiers, updateSelectedVendorIdentifiers] = useState<
    MarketplaceVendor[]
  >(() => [...defaultVendors]);
  const [retry, setRetry] = useState(0);
  const requestKey = JSON.stringify([
    version,
    os,
    arch,
    packageType,
    selectedVendorIdentifiers,
    retry,
  ]);
  const [request, setRequest] = useState<MarketplaceRequest>({
    key: "",
    releases: null,
    failed: false,
  });
  const currentRequest = request.key === requestKey;
  const releases = currentRequest ? request.releases : null;
  const failed = currentRequest && request.failed;

  const initializationKey = JSON.stringify([
    Array.from(searchParams?.entries() ?? []),
    oses,
    arches,
    latestLTS,
  ]);
  const [initializedKey, setInitializedKey] = useState<string | null>(null);

  // Synchronize browser defaults before committing a request with new URL parameters.
  if (
    searchParams &&
    oses.length > 0 &&
    arches.length > 0 &&
    initializedKey !== initializationKey
  ) {
    setInitializedKey(initializationKey);
    const params = Object.fromEntries(searchParams.entries());
    if (params.os === "alpine-linux") params.os = "alpine_linux";
    if (params.arch === "x32") params.arch = "x86";
    let defaultSelectedArch = defaultArchitecture;
    let defaultSelectedOS = "";
    let defaultSelectedPackageType = defaultPackageType;
    let defaultSelectedVersion = String(latestLTS ?? 25);

    // Arch param
    const hasExplicitArch = Boolean(
      params.arch &&
      (params.arch === "any" || arches.find((a) => a.value === params.arch)),
    );
    if (hasExplicitArch) {
      defaultSelectedArch = params.arch;
    }
    // OS param
    if (
      params.os &&
      (params.os === "any" || oses.find((os) => os.value === params.os))
    ) {
      defaultSelectedOS = params.os;
    } else {
      const userOS = detectOS();
      switch (userOS) {
        case UserOS.MAC:
          defaultSelectedOS = "mac";
          if (
            typeof window !== "undefined" &&
            typeof document !== "undefined"
          ) {
            const gl = document.createElement("canvas").getContext("webgl");
            const ext = gl && gl.getExtension("WEBGL_debug_renderer_info");
            const param =
              (ext && gl.getParameter(ext.UNMASKED_RENDERER_WEBGL)) || "";
            if (
              !hasExplicitArch &&
              param.match(/Apple/) &&
              !param.match(/Apple GPU/)
            ) {
              defaultSelectedArch = "aarch64";
            }
          }
          break;
        case UserOS.LINUX:
        case UserOS.UNIX:
          defaultSelectedOS = "linux";
          break;
        default:
          defaultSelectedOS = "windows";
          break;
      }
    }
    // Package type param
    if (
      params.package_type &&
      (params.package_type === "any" ||
        packageTypes.find((p) => p.value === params.package_type))
    ) {
      defaultSelectedPackageType = params.package_type;
    }
    // Version param
    if (params.version && typeof params.version === "string") {
      defaultSelectedVersion = params.version;
    }
    updateOS(defaultSelectedOS as OperatingSystem);
    updateArch(defaultSelectedArch as Architecture);
    updateVersion(defaultSelectedVersion);
    updatePackageType(defaultSelectedPackageType as ImageType);
    setReady(true);
  }

  useEffect(() => {
    if (!ready) return;
    let active = true;
    const pending =
      selectedVendorIdentifiers.length > 0
        ? getAllPkgsForVersion(
            Number(version),
            os,
            arch,
            packageType,
            selectedVendorIdentifiers,
          )
        : Promise.resolve<MarketplaceRelease[]>([]);
    pending
      .then((results) => {
        if (!active) return;
        if (results === null)
          console.error("Marketplace API returned no response for filters:", {
            version,
            os,
            arch,
            packageType,
            selectedVendorIdentifiers,
          });
        setRequest({
          key: requestKey,
          releases: results,
          failed: results === null,
        });
      })
      .catch((error) => {
        if (!active) return;
        console.error("Error fetching Marketplace releases:", error);
        setRequest({ key: requestKey, releases: null, failed: true });
      });
    return () => {
      active = false;
    };
  }, [
    ready,
    version,
    os,
    arch,
    packageType,
    selectedVendorIdentifiers,
    requestKey,
  ]);

  const versionUpdater = (version: string) => {
    setURLParam("version", version);
    updateVersion(version);
  };
  const archUpdater = (arch: string) => {
    setURLParam("arch", arch);
    updateArch(arch as Architecture);
  };
  const osUpdater = (os: string) => {
    setURLParam("os", os);
    updateOS(os as OperatingSystem);
  };
  const packageTypeUpdater = (pkg: string) => {
    setURLParam("package_type", pkg);
    updatePackageType(pkg as ImageType);
  };
  const handleReset = () => {
    const defaultOS: OperatingSystem = "any";
    const defaultArch: Architecture = defaultArchitecture;
    const defaultVersion = String(latestLTS ?? 25);
    const defaultPackage: ImageType = defaultPackageType;
    setURLParam("os", defaultOS);
    setURLParam("arch", defaultArch);
    setURLParam("version", defaultVersion);
    setURLParam("package_type", defaultPackage);
    updateOS(defaultOS);
    updateArch(defaultArch);
    updateVersion(defaultVersion);
    updatePackageType(defaultPackage);
    updateSelectedVendorIdentifiers(defaultVendors);
  };
  if (!ready)
    return (
      <div
        role="status"
        className="mx-auto max-w-7xl px-6 py-8 text-sm text-grey sm:px-8"
      >
        {t("Releases.loading")}
      </div>
    );
  return (
    <div className="mx-auto max-w-7xl px-6 pb-16 pt-6 sm:px-8">
      <div className="rounded-2xl border border-white/10 bg-white/[0.025] p-4">
        <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <h2 className="mb-0 text-sm font-semibold text-white">
              {tFilters("filter-releases")}
            </h2>
            <button
              type="button"
              aria-label={tFilters("filter-releases")}
              aria-expanded={filtersOpen}
              aria-controls={filterPanelId}
              data-testid="marketplace-toggle-filters"
              onClick={() => setFiltersOpen((open) => !open)}
              className="flex h-11 w-10 items-center justify-center rounded-lg border border-white/10 text-grey focus-visible:outline-2 focus-visible:outline-pink lg:hidden"
            >
              <FiChevronDown
                className={filtersOpen ? "rotate-180" : ""}
                aria-hidden="true"
              />
            </button>
          </div>
          <button
            type="button"
            onClick={handleReset}
            className="inline-flex min-h-11 items-center gap-2 text-xs text-grey transition-colors hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
          >
            <FiRotateCcw aria-hidden="true" />
            <span>{tFilters("reset-to-defaults")}</span>
          </button>
        </div>
        {!filtersOpen && (
          <p className="mb-0 text-xs leading-relaxed text-grey lg:hidden">{`JDK ${version} / ${os === "any" ? tFilters("any-os") : (oses.find((option) => option.value === os)?.name ?? os)} / ${arch === "any" ? tFilters("any-architecture") : os === "mac" && arch === "aarch64" ? "Apple Silicon" : arch} / ${packageType === "any" ? tFilters("any-package-type") : packageType.toUpperCase()}`}</p>
        )}
        <div
          id={filterPanelId}
          className={`${filtersOpen ? "block" : "hidden"} lg:block`}
        >
          <ReleaseSelector
            marketplace
            osOptions={oses}
            architectureOptions={arches}
            versions={ltsVersions}
            updateVersion={versionUpdater}
            defaultVersion={version}
            updateOS={osUpdater}
            defaultOS={os}
            updateArch={archUpdater}
            defaultArch={arch}
            defaultPackageType={packageType}
            updatePackageType={packageTypeUpdater}
          />
          <VendorSelector
            selectedVendorIdentifiers={selectedVendorIdentifiers}
            setSelectedVendorIdentifiers={(ids) =>
              updateSelectedVendorIdentifiers(toMarketplaceVendors(ids))
            }
          />
        </div>
      </div>
      {failed ? (
        <div
          role="alert"
          className="mt-8 rounded-xl border border-pink/30 bg-white/5 p-6 text-white"
        >
          <p className="mb-4 text-sm text-grey">{t("load-error")}</p>
          <button
            type="button"
            onClick={() => setRetry((value) => value + 1)}
            className="min-h-11 rounded-xl bg-pink px-4 py-2 text-sm font-semibold text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-white"
          >
            {t("retry")}
          </button>
        </div>
      ) : (
        <AllReleaseCard results={releases} onReset={handleReset} />
      )}
    </div>
  );
};

export default DownloadTable;
